{
  "technical_and_design_decisions": [
    "Use the corresponding upstream Hyperledger Fabric Go packages as external dependencies rather than maintaining copied implementations in the SDK.",
    "Pin Fabric dependencies to a compatible version and preserve the SDK's existing public behavior through import updates and small compatibility adapters where required.",
    "Prefer Go modules for dependency management, while retaining the minimum temporary chaincode-package go.mod handling required by U6.",
    "Remove obsolete copied or modified SDK implementations only after replacement packages compile and their behavior is covered by tests.",
    "Treat each migrated component as an incremental change, with focused unit tests followed by repository-wide integration and compatibility validation.",
    "Avoid changing Fabric protocols or business behavior; scope the work to dependency externalization, import/API adaptation, packaging, and the temporary module workaround."
  ],
  "assumptions": [
    "A compatible upstream Fabric release already provides the required gossip protoext, cauthdsl, ccprovider, ledger, common/core, configtxgen, and configtxlator functionality.",
    "The work is performed by one experienced Go developer familiar with Hyperledger Fabric and the Fabric Go SDK.",
    "The specification does not require publishing new upstream Fabric packages or coordinating changes with external Fabric maintainers.",
    "Existing SDK tests, fixtures, build scripts, and CI infrastructure can be reused with moderate updates.",
    "No major redesign of SDK APIs is required; incompatible upstream APIs can be handled with localized adapters.",
    "The temporary go.mod workaround applies only to chaincode package processing and will not become a general dependency-resolution redesign.",
    "Effort includes implementation, focused testing, debugging, and code review preparation, but excludes elapsed waiting time and external reviewer turnaround.",
    "The estimates include normal documentation and dependency metadata updates but not a full rewrite of user or developer documentation."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and dependency baseline",
      "activity_description": "Inventory the copied and modified Fabric packages, trace SDK imports and transitive dependencies, identify API differences from the selected upstream Fabric version, and define the migration sequence and acceptance checks.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize gossip protoext and discovery utilities",
      "activity_description": "Replace the SDK's modified gossip/discovery implementation with the external package, adapt imports and any required interfaces, remove obsolete code, and add or update focused tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize cauthdsl utilities",
      "activity_description": "Switch SDK consumers from the copied cauthdsl utilities to the upstream common package, resolve API or protobuf differences, remove the copied package, and update focused tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize ccprovider structures",
      "activity_description": "Adopt the external ccprovider package, adapt SDK code to its exported structures and helper APIs, remove the maintained copy, and verify provider-related behavior with focused tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ledger utilities",
      "activity_description": "Replace the copied ledger utilities with the external Fabric package, adjust imports and type usage, remove obsolete files, and validate ledger-related SDK functionality.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize common and core utilities",
      "activity_description": "Migrate consumers of the SDK's internal copies under fabric/common and fabric/core to upstream common/core packages, resolve dependency and visibility issues, remove duplicated implementations, and update focused tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize configtxgen functionality",
      "activity_description": "Replace the SDK's configtxgen-related resource and sdkinternal code with externalized Fabric functionality, preserve existing SDK resource behavior through adapters where necessary, and update configuration-generation tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxlator functionality",
      "activity_description": "Adopt the external configtxlator implementation, update SDK call sites and serialization handling, remove the copied implementation, and test translation and conversion behavior.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "SDK import, packaging, and copy removal refactor",
      "activity_description": "Consolidate go.mod requirements and replace remaining internal or third-party copy references, remove obsolete directories and generated artifacts, resolve name collisions, and ensure supported build targets compile.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "Temporary chaincode go.mod workaround",
      "activity_description": "Implement the transitional behavior that honors a go.mod file included in a chaincode package, constrain it to the intended packaging path, add regression tests, and document its temporary nature.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A11",
      "activity_name": "Cross-component integration and regression testing",
      "activity_description": "Run and repair unit, integration, packaging, configuration, discovery, and chaincode-related tests; validate behavior against representative SDK workflows; and diagnose dependency-version or platform-specific failures.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A12",
      "activity_name": "CI, dependency, and developer documentation updates",
      "activity_description": "Update dependency manifests, license or attribution files, build and CI configuration, migration notes, and developer documentation describing the externalized components and temporary module behavior.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A13",
      "activity_name": "Final quality validation and delivery preparation",
      "activity_description": "Perform final formatting, static analysis, vulnerability or dependency checks available in the repository, review the diff for accidental copied code, and prepare the increment for submission.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 68
  }
}

